cd /workspace && python3 - <<'PY'
import json,sys,subprocess
sys.path.insert(0,'/workspace/tmp/tests')
from ref import Image, Bad, Fib
req=json.dumps(json.load(open('/tmp/failreq.json')),separators=(',',':'))
p=subprocess.run([sys.executable,'run.py'],input=req.encode(),cwd='/workspace',capture_output=True)
resp=json.loads(p.stdout.decode())
results=resp['results']
req_v=json.loads(req)
for ci,(case,res) in enumerate(zip(req_v['cases'],results)):
    fib=Fib(); exp=[]; si=0; li=0; loaded=None; snaps=[]
    for op in case['ops']:
        if op[0]=='put': fib.put(op[1],op[2],op[3])
        elif op[0]=='query':
            for a in op[1]: exp.append(fib.lpm(a))
        elif op[0]=='image_query':
            for a in op[1]: exp.append(loaded.lookup(a) if loaded is not None else None)
        elif op[0]=='save': si+=1
        elif op[0]=='load_saved': loaded=Image(res['snapshots'][op[1]]); li+=1
        elif op[0]=='load':
            loaded=Image(op[1]) if res['loads'][li] else loaded; li+=1
    diffs=[(i,a,b) for i,(a,b) in enumerate(zip(exp,res['answers'])) if a!=b]
    print('case',ci,'ndiff',len(diffs), diffs[:3])
    if si!=len(res['snapshots']): print('  snapshot count mismatch', si, len(res['snapshots']))
    if li!=len(res['loads']): print('  load count mismatch', li, len(res['loads']))
